from fractions import Fraction
for i,(k,a) in enumerate([(4,3),(12,Fraction(1,3)),(5,Fraction(3,2)),(6,Fraction(1,2))],7):
 k,a=Fraction(k),Fraction(a);u=k*a;v=k*a*a;m=v-u;b=u-m
 def f(n):return str(n.numerator) if n.denominator==1 else r'\frac{%d}{%d}'%(n.numerator,n.denominator)
